// ────── tables/tables.dart ──────
import 'package:drift/drift.dart';

class Users extends Table {
  IntColumn get id => integer().autoIncrement()();
  TextColumn get name => text().withLength(min: 1, max: 100)();
  TextColumn get email => text().unique()();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();
}

class Orders extends Table {
  IntColumn get id => integer().autoIncrement()();
  IntColumn get userId => integer().references(Users, #id)();
  TextColumn get status => textEnum<OrderStatus>()();
  RealColumn get total => real()();
  DateTimeColumn get placedAt => dateTime().withDefault(currentDateAndTime)();
}
enum OrderStatus { pending, paid, shipped, delivered, cancelled }

// ────── database.dart ──────
import 'package:drift/drift.dart';
import 'package:drift_flutter/drift_flutter.dart';
import 'tables/tables.dart';
part 'database.g.dart';

@DriftDatabase(tables: [Users, Orders])
class AppDatabase extends _$AppDatabase {
  AppDatabase() : super(driftDatabase(name: 'app.sqlite'));

  @override int get schemaVersion => 2;

  @override
  MigrationStrategy get migration => MigrationStrategy(
    onCreate: (m) async => await m.createAll(),
    onUpgrade: (m, from, to) async {
      if (from < 2) {
        // add the placedAt column safely
        await m.addColumn(orders, orders.placedAt);
      }
    },
  );

  // ────── Typed queries ──────
  Future<List<User>> allUsers() => select(users).get();
  Stream<List<User>> watchAllUsers() => select(users).watch();

  Future<int> addUser(UsersCompanion u) => into(users).insert(u);

  Stream<List<OrderWithUser>> watchRecentOrders() {
    final q = select(orders).join([leftOuterJoin(users, users.id.equalsExp(orders.userId))])
      ..orderBy([OrderingTerm.desc(orders.placedAt)])
      ..limit(50);
    return q.watch().map((rows) => rows.map((r) =>
      OrderWithUser(order: r.readTable(orders), user: r.readTableOrNull(users))
    ).toList());
  }

  Future<double> monthRevenue() async {
    final total = orders.total.sum();
    final row = await (selectOnly(orders)
      ..addColumns([total])
      ..where(orders.placedAt.isBiggerOrEqualValue(DateTime.now().subtract(const Duration(days: 30))))
    ).getSingle();
    return row.read(total) ?? 0;
  }
}

class OrderWithUser { final Order order; final User? user; OrderWithUser({required this.order, required this.user}); }

// Regen: dart run build_runner watch --delete-conflicting-outputs

// Any query has a .watch() counterpart — Streams update whenever affected tables change.
class UserList extends StatelessWidget {
  const UserList({super.key, required this.db});
  final AppDatabase db;
  @override
  Widget build(BuildContext context) {
    return StreamBuilder<List<User>>(
      stream: db.watchAllUsers(),
      builder: (ctx, snap) {
        if (!snap.hasData) return const CircularProgressIndicator();
        final users = snap.data!;
        return ListView.builder(
          itemCount: users.length,
          itemBuilder: (_, i) => ListTile(title: Text(users[i].name)),
        );
      },
    );
  }
}

// Insert from elsewhere:
db.addUser(UsersCompanion.insert(name: 'Ada', email: 'ada@x'));
// UserList's Stream fires — UI rebuilds. No manual invalidation.
